    void show() { System.out.print("A "); }
}
class B extends A {
    @Override
    void show() { System.out.print("B "); }
}
class C extends B {}
public class Main {
    public static void main(String[] args) {
        A ref = new C();
        ref.show();
    }
}
```

What is the output of the following private method non-dispatch program?
```java
class SuperSecret {
    public void reveal() {
        identify();
    }
    private void identify() {
        System.out.print("SuperSecret ");
    }
}
class SubSecret extends SuperSecret {
    public void identify() {
        System.out.print("SubSecret ");
    }
}
public class Main {
    public static void main(String[] args) {
        SuperSecret ss = new SubSecret();
        ss.reveal();
    }
}
```

What is the output of the following constructor dispatch program?
```java
class ParentWorker {
    ParentWorker() {
        work();
    }
    void work() {
        System.out.print("ParentWork ");
    }
}
class ChildWorker extends ParentWorker {
    String task = "Coding";
    @Override
    void work() {
        System.out.print("Child:" + task + " ");
    }
}
public class Main {
    public static void main(String[] args) {
        new ChildWorker();
    }
}
```

What is the output of the following super.method() dispatch program?
```java
class X {
    void step() { System.out.print("X "); }
}
class Y extends X {
    @Override
    void step() {
        super.step();
        System.out.print("Y ");
    }
}
class Z extends Y {
    @Override
    void step() {
        super.step();
        System.out.print("Z ");
    }
}
public class Main {
    public static void main(String[] args) {
        X ref = new Z();
        ref.step();
    }
}
```

What is the output of the following overloaded vs overridden dispatch program?
```java
class Formatter {
    void format(Object o) { System.out.print("Obj "); }
    void format(String s) { System.out.print("Str "); }
}
class CustomFormatter extends Formatter {
    @Override
    void format(Object o) { System.out.print("CustomObj "); }
}
public class Main {
    public static void main(String[] args) {
        Formatter f = new CustomFormatter();
        Object obj = "hello";
        f.format(obj);
    }
}
```

